(()=>{"use strict";const S={hunPIN:[3,3,3],hunCRID:[2,2,6],hunTID:[8,1,2]};for(const[t,n]of Object.entries(S))HTMLControlGenerator.register(t,e=>{const t=String(e.value??""),o=jQuery("<span>").attr("id",e.id).addClass(e.class);let a=0;return n.forEach((n,r)=>{r>0&&o.append(jQuery("<span>").attr("id",`${e.id}_spacer_${r-1}`).addClass(`${e.id}SpacerClass`).text(" - ")),o.append(HTMLControlGenerator.create({inputType:"number",id:`${e.id}_${r}`,class:e.inputClass,value:t.slice(a,a+n),min:0,max:10**n-1})),a+=n}),o})})();
